$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root 'pubspec.yaml'))) {
    throw 'Run this script from the almustafa-connect-erp project root.'
}

$utf8 = New-Object System.Text.UTF8Encoding($false)
$target = 'lib/features/fees/presentation/pages/student_fee_assignment_page.dart'
$targetPath = Join-Path $root $target

if (-not (Test-Path $targetPath)) {
    throw "Required file not found: $target"
}

$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$backupRoot = Join-Path `
    (Split-Path $root -Parent) `
    "almustafa-connect-erp_backups/student_fee_assignment_class_first_$stamp"

$backupFile = Join-Path $backupRoot $target

New-Item `
    -ItemType Directory `
    -Path (Split-Path $backupFile -Parent) `
    -Force | Out-Null

Copy-Item $targetPath $backupFile -Force

$content = [Text.Encoding]::UTF8.GetString(
    [Convert]::FromBase64String('')
)

[IO.File]::WriteAllText($targetPath, $content, $utf8)
Write-Host "Updated: $target" -ForegroundColor Green

Write-Host ''
Write-Host 'Running dart format...' -ForegroundColor Cyan

& dart format $target

if ($LASTEXITCODE -ne 0) {
    throw 'dart format failed.'
}

Write-Host ''
Write-Host 'Running flutter analyze...' -ForegroundColor Cyan

& flutter analyze

if ($LASTEXITCODE -ne 0) {
    throw 'flutter analyze found issues. Copy the complete output into ChatGPT.'
}

Write-Host ''
Write-Host 'Student Fee Assignment class-first workflow completed successfully.' -ForegroundColor Green
Write-Host 'Class selection, student filtering, bulk assignment and individual fee adjustment are now available.' -ForegroundColor Cyan
Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray
